fun restoreBackupJson(json: String, onResult: (errors: List<String>) -> Unit) {
    viewModelScope.launch {
        val (payload, parseError) = DataBackupValidator.parseJson(json)
        if (payload == null) {
            onResult(listOf(parseError ?: getApplication<Application>().getString(R.string.error_failed_parse_backup)))
            return@launch
        }
        val validationErrors = DataBackupValidator.validate(payload)
        if (validationErrors.isNotEmpty()) {
            onResult(validationErrors)
            return@launch
        }
        db.withTransaction {
            profileRepository.deleteAll()
            medicationRepository.deleteAll()
            doseLogRepository.deleteAll()
            payload.profiles.forEach { profileRepository.insert(it.toEntity()) }
            payload.medications.forEach { medicationRepository.insert(it.toEntity()) }
            payload.doseLogs.forEach { doseLogRepository.insert(it.toEntity()) }
        }
        onResult(emptyList())
    }
}
